-- ===========================================================================
-- Part 2: security (hand-written — review carefully)
-- Same rules as the tenancy migration: RLS enabled + forced, explicit grants only,
-- policies keyed on current_tenant_id(). kenisha_platform gets NOTHING here.
-- ===========================================================================

-- Data checks ------------------------------------------------------------------
ALTER TABLE "users"
  ADD CONSTRAINT "users_phone_e164" CHECK ("phone_e164" ~ '^\+[1-9][0-9]{6,14}$'),
  ADD CONSTRAINT "users_email_lowercase" CHECK ("email" IS NULL OR "email" = lower("email"));
ALTER TABLE "otp_challenges"
  ADD CONSTRAINT "otp_challenges_phone_e164" CHECK ("phone_e164" ~ '^\+[1-9][0-9]{6,14}$'),
  ADD CONSTRAINT "otp_challenges_code_hmac_hex" CHECK ("code_hmac" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "otp_challenges_attempts_range" CHECK ("attempts" >= 0 AND "attempts" <= "max_attempts");
ALTER TABLE "sessions"
  ADD CONSTRAINT "sessions_refresh_hash_hex" CHECK ("refresh_token_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "sessions_expiry_order" CHECK ("expires_at" <= "absolute_expires_at");
ALTER TABLE "audit_events"
  ADD CONSTRAINT "audit_events_action_format" CHECK ("action" ~ '^[A-Z][A-Z0-9_]{2,63}$');

-- Hospital lookup before login (ADR-0003 §1) ----------------------------------------
-- Login runs before any tenant context exists. This SECURITY DEFINER function returns
-- only (id, is_active) for one hospital code — nothing else about any tenant.
-- It runs as the schema owner, which under FORCE RLS needs its own read policy.
CREATE POLICY "tenants_owner_resolve" ON "tenants" FOR SELECT TO kenisha_migrator USING (true);

CREATE FUNCTION "resolve_tenant"(p_code text)
  RETURNS TABLE (tenant_id uuid, is_active boolean)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT t.id, t.status = 'ACTIVE'
    FROM kenisha.tenants t
    WHERE t.slug = lower(p_code)
  $$;

REVOKE ALL ON FUNCTION "resolve_tenant"(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "resolve_tenant"(text) TO kenisha_app;

-- Hospital admins choose the staff second-factor scope (ADR-0003, I5).
GRANT UPDATE ("staff_mfa_mode") ON "tenants" TO kenisha_app;

-- users -------------------------------------------------------------------------------
ALTER TABLE "users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "users" FORCE ROW LEVEL SECURITY;
GRANT SELECT, INSERT ON "users" TO kenisha_app;
GRANT UPDATE ("display_name", "phone_e164", "email", "status", "updated_at") ON "users" TO kenisha_app;
CREATE POLICY "users_tenant_isolation" ON "users" TO kenisha_app
  USING ("tenant_id" = (SELECT "current_tenant_id"()))
  WITH CHECK ("tenant_id" = (SELECT "current_tenant_id"()));

-- user_roles (DELETE allowed: removing a role) ----------------------------------------
ALTER TABLE "user_roles" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "user_roles" FORCE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, DELETE ON "user_roles" TO kenisha_app;
CREATE POLICY "user_roles_tenant_isolation" ON "user_roles" TO kenisha_app
  USING ("tenant_id" = (SELECT "current_tenant_id"()))
  WITH CHECK ("tenant_id" = (SELECT "current_tenant_id"()));

